// Shared money-clip cache for WP tags. Timestamp-based freshness
// against /api/wp_cache/_timestamps (see publications_cache.js for the
// pattern).

import { getConfiguredCache } from 'money-clip'
import { timestampFromResponse } from './wp_cache_timestamps'
import { staleWhileRevalidate } from './wp_cache_swr'

// Server-side change detection (wp_cache compares old vs new payload and
// reuses fetched_at when unchanged) means the timestamp gate is the only
// invalidator we need. No need to evict by age.
const tagsRawCache = getConfiguredCache({
  maxAge: Infinity,
  version: 2,
  name: 'tagsRaw',
})

const TAGS_URL = '/api/wp_cache/tags'
const RESOURCE = 'tags'

function fetchAndCache() {
  return fetch(TAGS_URL, { headers: { Accept: 'application/json' } })
    .then((r) => {
      if (!r.ok) throw new Error(`tags ${r.status}`)
      const ts = timestampFromResponse(r)
      return r.json().then((rows) => {
        if (rows && rows.length) {
          tagsRawCache.set('all', { data: rows, fetched_at: ts })
        }
        return rows
      })
    })
}

// `onFresh` is called if revalidation finds a newer copy on the server, so a
// cached list can render immediately and update in place a moment later.
export function loadTags(onFresh) {
  return tagsRawCache.get('all').then((cached) =>
    staleWhileRevalidate({
      cached: _unwrap(cached),
      resource: RESOURCE,
      refetch: fetchAndCache,
      onFresh,
    }),
  )
}

function _unwrap(cached) {
  if (!cached) return null
  if (Array.isArray(cached)) {
    return cached.length ? { data: cached, fetched_at: 0 } : null
  }
  if (cached.data && Array.isArray(cached.data) && cached.data.length) {
    return { data: cached.data, fetched_at: cached.fetched_at || 0 }
  }
  return null
}
